contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v, address a) public payable {
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetLogFile(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.MinSum() == minSumBefore);
    }
    receive() external payable {}
}

