// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 v, address a) internal {
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        bool reverted;
        try c.SetLogFile(a) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.MinSum() == minSumBefore);
    }

    function testFuzz_run(uint256 v, address a) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(v, a);
    }

    receive() external payable {}
}
